var pi = doc.ProjectInformation;
var piParams = new List<object>();
foreach (Parameter p in pi.Parameters) {
  string v = p.StorageType == StorageType.String ? p.AsString() : p.AsValueString();
  if (!string.IsNullOrWhiteSpace(v)) piParams.Add(new { n = p.Definition.Name, v });
}
var revs = new FilteredElementCollector(doc).OfClass(typeof(Revision)).Cast<Revision>()
  .Select(r => new { seq = r.SequenceNumber, date = r.RevisionDate, desc = r.Description, issued = r.Issued }).ToList();
var tbs = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_TitleBlocks).WhereElementIsNotElementType()
  .Cast<FamilyInstance>().GroupBy(t => t.Symbol.FamilyName + " : " + t.Symbol.Name).Select(g => new { tb = g.Key, n = g.Count() }).ToList();
var tbYesNo = new List<object>();
var tb1 = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_TitleBlocks).WhereElementIsNotElementType().FirstElement();
if (tb1 != null) foreach (Parameter p in tb1.Parameters) if (p.StorageType == StorageType.Integer && p.Definition.GetDataType() == SpecTypeId.Boolean.YesNo) tbYesNo.Add(new { n = p.Definition.Name, v = p.AsInteger() });
var cad = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Cast<ImportInstance>()
  .GroupBy(i => (i.Category != null ? i.Category.Name : "?") + "|linked:" + i.IsLinked + "|viewSpecific:" + i.ViewSpecific).Select(g => new { k = g.Key, n = g.Count() }).ToList();
var schedOnSheets = new FilteredElementCollector(doc).OfClass(typeof(ScheduleSheetInstance)).Cast<ScheduleSheetInstance>().Count(s => !s.IsTitleblockRevisionSchedule);
var inPlace = new FilteredElementCollector(doc).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Count(f => f.Symbol.Family.IsInPlace);
var modelCats = new FilteredElementCollector(doc).WhereElementIsNotElementType().Where(e => e.Category != null && e.Category.CategoryType == CategoryType.Model && !(e is RevitLinkInstance))
  .GroupBy(e => e.Category.Name).Select(g => new { c = g.Key, n = g.Count() }).OrderByDescending(x => x.n).Take(15).ToList();
return new { piParams, revs, tbs, tbYesNo, cad, schedOnSheets, inPlace, modelCats };
